import axios from 'axios';
import { useState, useEffect } from 'react';
import { Link, useParams, useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';
import api, { PEXELS_KEY, API_URL } from '../api';

// ─── IMAGE SEARCH ──────────────────────────────────────────────────────────────
const SUGGESTIONS = ['Nature','Technology','Travel','Architecture','People','Food','Space','Art','Business','Fashion'];

export function ImageSearch() {
  const [query, setQuery] = useState('');
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [selected, setSelected] = useState(null);
  const [error, setError] = useState('');

  const search = async (q = query, pg = 1) => {
    if (!q.trim()) return;
    setLoading(true); setError('');
    try {
      const { data } = await axios.get('https://api.pexels.com/v1/search', {
        headers: { Authorization: PEXELS_KEY },
        // params: { query: q, per_page: 15, page: pg, orientation: 'landscape' },
        params: { query: q, per_page: 15, page: pg },
      });
      setImages(pg === 1 ? data.photos : prev => [...prev, ...data.photos]);
      setTotal(data.total_results);
      setPage(pg);
    } catch { setError('Failed to load images. Try again.'); }
    finally { setLoading(false); }
  };

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div style={is.header}>
        <div className="container">
          <h1 style={is.title}>Image Search</h1>
          <p style={is.sub}>Millions of free high-quality photos powered by Pexels</p>
          <div style={is.searchBar}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#9b9b9b" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            <input style={is.searchInput} placeholder="Search for photos..."
              value={query}
              onChange={e => setQuery(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && search(query, 1)} />
            <button style={is.searchBtn} onClick={() => search(query, 1)}>Search</button>
          </div>
          <div style={is.chips}>
            {SUGGESTIONS.map(s => (
              <button key={s} style={is.chip} onClick={() => { setQuery(s); setTimeout(() => search(s, 1), 300); }}>{s}</button>
            ))}
          </div>
        </div>
      </div>

      <div className="container" style={{ paddingBottom: 60 }}>
        {error && <div style={is.error}>{error}</div>}

        {!loading && images.length === 0 && (
          <div style={is.empty}>
            <div style={{ fontSize: 64, marginBottom: 16 }}>🔍</div>
            <h3 style={{ fontFamily: 'Lora, serif', fontSize: 22, marginBottom: 8 }}>Explore beautiful photos</h3>
            <p style={{ color: '#9b9b9b', fontSize: 15 }}>Search for any topic above to get started.</p>
          </div>
        )}

        {images.length > 0 && (
          <>
            <div style={{ fontSize: 13, color: '#9b9b9b', margin: '24px 0 16px' }}>
              {total.toLocaleString()} results for "{query}"
            </div>
            <div style={is.grid}>
              {images.map(img => (
               <div key={img.id} style={is.card}
  onMouseEnter={e => { e.currentTarget.querySelector('.overlay').style.opacity = '1'; e.currentTarget.querySelector('.dlbtn').style.opacity = '1'; }}
  onMouseLeave={e => { e.currentTarget.querySelector('.overlay').style.opacity = '0'; e.currentTarget.querySelector('.dlbtn').style.opacity = '0'; }}
  onClick={() => setSelected(img)}>
  <img src={img.src.medium} alt={img.alt} style={is.img} />
  <div className="overlay" style={is.overlay}>
    <span style={is.photographer}>📷 {img.photographer}</span>
  </div>
  <a href={img.src.original} download target="_blank" rel="noreferrer"
    className="dlbtn"
    style={is.dlBtn}
    onClick={e => e.stopPropagation()}>
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
  </a>
</div>

              ))}
              {loading && Array.from({ length: 6 }).map((_, i) => (
                <div key={`sk${i}`} className="skeleton" style={{ height: 200, borderRadius: 4 }} />
              ))}
            </div>
            {images.length < total && (
              <div style={{ textAlign: 'center', marginTop: 40 }}>
                <button style={is.loadMore} onClick={() => search(query, page + 1)} disabled={loading}>
                  {loading ? 'Loading...' : 'Load more'}
                </button>
              </div>
            )}
          </>
        )}
      </div>

      {selected && (
        <div style={is.lightbox} onClick={() => setSelected(null)}>
          <div style={is.lightboxBox} onClick={e => e.stopPropagation()}>
            <button style={is.closeBtn} onClick={() => setSelected(null)}>✕</button>
            <img src={selected.src.large} alt={selected.alt} style={is.lightboxImg} />
            <div style={is.lightboxFooter}>
              <div>
                <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4 }}>{selected.alt || 'Photo'}</div>
                <div style={{ fontSize: 13, color: '#9b9b9b' }}>by <strong>{selected.photographer}</strong> on Pexels</div>
              </div>
              <div style={{ display: 'flex', gap: 10 }}>
                <a href={selected.url} target="_blank" rel="noreferrer" style={is.viewBtn}>View on Pexels</a>
                <a href={selected.src.original} download target="_blank" rel="noreferrer" style={is.dlBtn2}>↓ Original</a>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── PROFILE ──────────────────────────────────────────────────────────────────
export function Profile() {
  const { id } = useParams();
  const { user: me } = useAuth();
  const [profile, setProfile] = useState(null);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('posts');
  const [following, setFollowing] = useState(false);

  useEffect(() => {
    Promise.all([
      api.get(`/auth/${id}`),
      api.get(`/posts?author=${id}`)
    ]).then(([u, p]) => {
      setProfile(u.data);
      setPosts(p.data.posts);
      if (me) setFollowing(u.data.followers?.includes(me.id));
    }).catch(console.error).finally(() => setLoading(false));
  }, [id, me]);

  const handleFollow = async () => {
    if (!me) return;
    try {
      await api.post(`/auth/${id}/follow`);
      setFollowing(f => !f);
      setProfile(p => ({ ...p, followers: following ? p.followers.filter(f => f !== me.id) : [...p.followers, me.id] }));
    } catch {}
  };

  if (loading) return <div style={{ padding: 60, textAlign: 'center' }}>Loading...</div>;
  if (!profile) return <div style={{ padding: 60, textAlign: 'center' }}>User not found</div>;
  const isMe = me?.id === id;

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div className="container" style={{ maxWidth: 960, padding: '60px 24px' }}>
        <div style={pr.header}>
          <div>
            <h1 style={pr.name}>{profile.name}</h1>
            {profile.bio && <p style={pr.bio}>{profile.bio}</p>}
            <div style={pr.stats}>
              <span style={pr.stat}><strong>{profile.followers?.length || 0}</strong> Followers</span>
              <span style={pr.stat}><strong>{profile.following?.length || 0}</strong> Following</span>
              <span style={pr.stat}><strong>{posts.length}</strong> Stories</span>
            </div>
            {!isMe && me && (
              <button onClick={handleFollow} style={following ? pr.followingBtn : pr.followBtn}>
                {following ? 'Following' : 'Follow'}
              </button>
            )}
          </div>
          <div style={pr.avatarBig}>{profile.name?.[0]?.toUpperCase()}</div>
        </div>

        <div style={pr.tabs}>
          <button style={{ ...pr.tab, ...(tab === 'posts' ? pr.tabActive : {}) }} onClick={() => setTab('posts')}>Stories</button>
          {isMe && <button style={{ ...pr.tab, ...(tab === 'about' ? pr.tabActive : {}) }} onClick={() => setTab('about')}>About</button>}
        </div>

        {tab === 'posts' && (
          posts.length === 0
            ? <div style={{ padding: '60px 0', color: '#9b9b9b', fontSize: 16 }}>No stories published yet.</div>
            : posts.map(p => <PostCard key={p._id} post={p} />)
        )}

        {tab === 'about' && isMe && (
          <div style={{ maxWidth: 480, paddingTop: 32 }}>
            <div style={pr.aboutRow}><span style={pr.aboutLabel}>Name</span><span>{profile.name}</span></div>
            <div style={pr.aboutRow}><span style={pr.aboutLabel}>Bio</span><span>{profile.bio || '—'}</span></div>
            <div style={pr.aboutRow}><span style={pr.aboutLabel}>Joined</span><span>{new Date(profile.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long' })}</span></div>
          </div>
        )}
      </div>
    </div>
  );
}

// ─── BOOKMARKS ────────────────────────────────────────────────────────────────
export function Bookmarks() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get('/auth/me').then(r => {
      setPosts(r.data.bookmarks || []);
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div style={{ maxWidth: 728, margin: '0 auto', padding: '48px 24px' }}>
        <h1 style={{ fontFamily: 'Lora, serif', fontSize: 36, fontWeight: 700, marginBottom: 40 }}>Reading list</h1>
        {loading ? <div>Loading...</div>
          : posts.length === 0
            ? <div style={{ color: '#9b9b9b', fontSize: 16 }}>No bookmarks yet. Save stories to read later.</div>
            : posts.map(p => <PostCard key={p._id} post={{ ...p, author: { name: 'Author' } }} />)
        }
      </div>
    </div>
  );
}

// ─── SEARCH ───────────────────────────────────────────────────────────────────
export function Search() {
  const [searchParams] = useSearchParams();
  const q = searchParams.get('q') || '';
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!q) return setLoading(false);
    api.get(`/posts?search=${encodeURIComponent(q)}`).then(r => setPosts(r.data.posts)).catch(() => {}).finally(() => setLoading(false));
  }, [q]);

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div style={{ maxWidth: 728, margin: '0 auto', padding: '48px 24px' }}>
        <h1 style={{ fontFamily: 'Lora, serif', fontSize: 28, fontWeight: 700, marginBottom: 8 }}>
          Results for "{q}"
        </h1>
        <p style={{ color: '#9b9b9b', fontSize: 14, marginBottom: 32 }}>{posts.length} stories found</p>
        {loading ? <div>Searching...</div>
          : posts.length === 0
            ? <div style={{ color: '#9b9b9b' }}>No stories matched your search.</div>
            : posts.map(p => <PostCard key={p._id} post={p} />)
        }
      </div>
    </div>
  );
}

// ─── TAG PAGE ─────────────────────────────────────────────────────────────────
export function TagPage() {
  const { tag } = useParams();
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const displayTag = tag.charAt(0).toUpperCase() + tag.slice(1);

  useEffect(() => {
    api.get(`/posts?category=${displayTag}`).then(r => setPosts(r.data.posts)).catch(() => {}).finally(() => setLoading(false));
  }, [tag, displayTag]);

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div style={{ borderBottom: '1px solid #e6e6e6', padding: '40px 0' }}>
        <div className="container" style={{ maxWidth: 960 }}>
          <div style={{ display: 'inline-block', padding: '8px 20px', border: '1px solid #242424', borderRadius: 999, fontSize: 14, fontWeight: 500, marginBottom: 12 }}>{displayTag}</div>
          <h1 style={{ fontFamily: 'Lora, serif', fontSize: 42, fontWeight: 700, marginBottom: 8 }}>{displayTag}</h1>
          <p style={{ color: '#9b9b9b', fontSize: 15 }}>{posts.length} stories</p>
        </div>
      </div>
      <div className="container" style={{ maxWidth: 960, padding: '0 24px' }}>
        <div style={{ maxWidth: 728 }}>
          {loading ? <div style={{ padding: 40 }}>Loading...</div>
            : posts.length === 0
              ? <div style={{ padding: '60px 0', color: '#9b9b9b' }}>No stories in this topic yet.</div>
              : posts.map(p => <PostCard key={p._id} post={p} />)
          }
        </div>
      </div>
    </div>
  );
}

// ─── DRAFTS ───────────────────────────────────────────────────────────────────
export function Drafts() {
  const [drafts, setDrafts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [deleting, setDeleting] = useState(null);
  const navigate = useNavigate();

  const fetchDrafts = () => {
    setLoading(true);
    api.get('/posts/my-drafts')
      .then(r => setDrafts(Array.isArray(r.data) ? r.data : r.data.drafts || []))
      .catch(() => setDrafts([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchDrafts(); }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this draft?')) return;
    setDeleting(id);
    try {
      await api.delete(`/posts/${id}`);
      setDrafts(d => d.filter(x => x._id !== id));
    } catch {}
    setDeleting(null);
  };

  const handleEdit = (id) => {
    navigate(`/write/draft/${id}`);
  };

  const handlePublish = async (id) => {
    try {
      await api.put(`/posts/${id}`, { isDraft: false });
      setDrafts(d => d.filter(x => x._id !== id));
      navigate('/');
    } catch {}
  };

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <div style={{ maxWidth: 728, margin: '0 auto', padding: '48px 24px' }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 40 }}>
          <div>
            <h1 style={{ fontFamily: 'Lora, serif', fontSize: 36, fontWeight: 700, marginBottom: 6 }}>Your Drafts</h1>
            <p style={{ color: '#9b9b9b', fontSize: 15 }}>{drafts.length} draft{drafts.length !== 1 ? 's' : ''} saved</p>
          </div>
          <button
            onClick={() => navigate('/write')}
            style={{ padding: '10px 24px', background: '#242424', color: '#fff', border: 'none', borderRadius: 999, fontSize: 14, fontWeight: 500, cursor: 'pointer' }}>
            + New story
          </button>
        </div>

        {/* Content */}
        {loading ? (
          <div style={{ padding: '60px 0', textAlign: 'center', color: '#9b9b9b' }}>Loading drafts...</div>
        ) : drafts.length === 0 ? (
          <div style={{ padding: '80px 0', textAlign: 'center' }}>
            <div style={{ fontSize: 56, marginBottom: 16 }}>📝</div>
            <h3 style={{ fontFamily: 'Lora, serif', fontSize: 22, marginBottom: 8 }}>No drafts yet</h3>
            <p style={{ color: '#9b9b9b', fontSize: 15, marginBottom: 24 }}>Start writing and save your work as a draft.</p>
            <button
              onClick={() => navigate('/write')}
              style={{ padding: '10px 28px', background: '#242424', color: '#fff', border: 'none', borderRadius: 999, fontSize: 14, fontWeight: 500, cursor: 'pointer' }}>
              Start writing
            </button>
          </div>
        ) : (
          <div>
            {drafts.map(draft => (
              <div key={draft._id} style={dr.card}>
                <div style={dr.cardBody}>
                  {/* Title */}
                  <h2 style={dr.title}>{draft.title || 'Untitled draft'}</h2>

                  {/* Excerpt */}
                  {draft.content && (
                    <p style={dr.excerpt}>
                      {draft.content.replace(/<[^>]*>/g, '').substring(0, 120)}
                      {draft.content.length > 120 ? '...' : ''}
                    </p>
                  )}

                  {/* Meta */}
                  <div style={dr.meta}>
                    <span style={dr.date}>
                      Last saved {new Date(draft.updatedAt || draft.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                    </span>
                    {draft.category && (
                      <span style={dr.tag}>{draft.category}</span>
                    )}
                  </div>
                </div>

                {/* Actions */}
                <div style={dr.actions}>
                  <button onClick={() => handleEdit(draft._id)} style={dr.editBtn}>Edit</button>
                  <button onClick={() => handlePublish(draft._id)} style={dr.publishBtn}>Publish</button>
                  <button
                    onClick={() => handleDelete(draft._id)}
                    disabled={deleting === draft._id}
                    style={dr.deleteBtn}>
                    {deleting === draft._id ? '...' : 'Delete'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── STYLES ───────────────────────────────────────────────────────────────────
const is = {
  header: { background: '#fafafa', borderBottom: '1px solid #e6e6e6', padding: '56px 0 32px' },
  title: { fontFamily: 'Lora, serif', fontSize: 40, fontWeight: 700, color: '#242424', marginBottom: 8 },
  sub: { fontSize: 16, color: '#9b9b9b', marginBottom: 28 },
  searchBar: { display: 'flex', alignItems: 'center', gap: 12, maxWidth: 580, background: '#fff', border: '1px solid #e6e6e6', borderRadius: 999, padding: '8px 8px 8px 20px' },
  searchInput: { flex: 1, border: 'none', outline: 'none', fontSize: 15, color: '#242424', background: 'none' },
  searchBtn: { padding: '10px 24px', background: '#242424', color: '#fff', border: 'none', borderRadius: 999, fontSize: 14, fontWeight: 600, cursor: 'pointer', flexShrink: 0 },
  chips: { display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 20 },
  chip: { padding: '6px 16px', borderRadius: 999, border: '1px solid #e6e6e6', background: '#fff', fontSize: 13, cursor: 'pointer', color: '#6b6b6b' },
  error: { padding: '12px', background: '#fff8f8', border: '1px solid #ffd0d0', borderRadius: 4, fontSize: 13, color: '#c00', margin: '24px 0' },
  empty: { textAlign: 'center', padding: '100px 0' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 16, marginTop: 8 },
  card: { position: 'relative', borderRadius: 4, overflow: 'hidden', cursor: 'pointer', background: '#f2f2f2' },
  img: { width: '100%', height: 200, objectFit: 'cover', display: 'block', transition: 'transform 0.3s' },
  overlay: { position: 'absolute', inset: 0, background: 'linear-gradient(to top, rgba(0,0,0,0.7), transparent)', opacity: 0, transition: 'opacity 0.2s', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', padding: 12 },
  photographer: { fontSize: 12, color: '#fff', fontWeight: 500 },
  dlBtn: { position: 'absolute', top: 10, right: 10, width: 36, height: 36, borderRadius: '50%', background: '#e30d10', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: 0, transition: 'opacity 0.2s, background 0.15s', border: 'none', cursor: 'pointer', zIndex: 10, boxShadow: '0 2px 8px rgba(0,0,0,0.2)' },
  // dlBtn: { padding: '5px 12px', background: 'rgba(255,255,255,0.9)', color: '#242424', borderRadius: 4, fontSize: 12, fontWeight: 600, border: 'none', cursor: 'pointer', transition: 'background 0.2s' },
